    'web.channels.settings.behaviors.autoThreadServerDescription': 'Démarrez un fil public depuis le message déclencheur lorsqu’un message du serveur n’est pas déjà dans un fil.',
    'web.channels.settings.behaviors.ackReaction': 'Réagir avec 👀 pendant le travail',
    'web.channels.settings.behaviors.ackReactionDescription': 'Ajoutez une réaction 👀 au message déclencheur pendant le travail de l’agent ; elle est supprimée lorsque la réponse est terminée. L’état de saisie est toujours affiché.',
    'web.channels.settings.behaviors.finalNewMessage': 'Publier la réponse finale comme nouveau message',
    'web.channels.settings.behaviors.finalNewMessageTelegramDescription': 'Supprimez l’aperçu en streaming et envoyez la réponse finale comme nouveau message afin que Telegram envoie une notification push (les messages modifiés ne déclenchent jamais de notification).',
    'web.channels.settings.behaviors.finalNewMessageDiscordDescription': 'Supprimez l’aperçu en streaming et envoyez la réponse finale comme nouveau message afin que Discord envoie une notification push.',
    'web.channels.settings.behaviors.usageFooter': 'Ajouter un pied de page d’utilisation aux réponses',
    'web.channels.settings.behaviors.usageFooterDescription': 'Ajoutez un résumé sur une ligne (modèle · jetons · coût · durée · outils) à la fin de chaque réponse.',
    'web.channels.settings.behaviors.githubFreshComment': 'Publier la réponse finale comme nouveau commentaire',
    'web.channels.settings.behaviors.githubFreshCommentDescription': 'GitHub n’envoie jamais de notification lors de la modification d’un commentaire ; un nouveau commentaire remplace l’aperçu et déclenche les notifications des abonnés.',
    'web.channels.settings.behaviors.mentionOnly': 'Mention uniquement (groupes)',
    'web.channels.settings.behaviors.mentionOnlyDescription': 'Répondez uniquement lorsqu’une mention @ est utilisée dans les chats de groupe.',
    'web.channels.settings.behaviors.shareSession': 'Partager la session dans le canal',
    'web.channels.settings.behaviors.shareSessionDescription': 'Tous les membres du groupe partagent une session de chat (sinon, une par utilisateur).',
    'web.channels.settings.behaviors.threadIsolation': 'Isolation des fils',
    'web.channels.settings.behaviors.sendContext': 'Envoyer le contexte du message à l’agent',
    'web.channels.settings.behaviors.sendContextDescription': 'Ajoutez les métadonnées du canal (expéditeur, ID des messages) à chaque message entrant afin que l’agent sache qui l’a envoyé.',
    'web.channels.settings.behaviors.sendContextFullDescription': 'Ajoutez les métadonnées du canal (expéditeur, chat, fil, ID des messages) à chaque message entrant afin que l’agent sache qui l’a envoyé et d’où il vient.',
    'web.channels.settings.threadLabels.lark': 'Chaque fil de messages possède sa propre session.',
    'web.channels.settings.threadLabels.telegram': 'Chaque sujet ou fil de réponse Telegram possède sa propre session.',
    'web.channels.settings.threadLabels.slack': 'Chaque fil Slack possède sa propre session.',
    'web.channels.settings.threadLabels.discord': 'Chaque fil Discord possède sa propre session ; les réponses restent dans le fil.',
    'web.channels.settings.threadLabels.matrix': 'Chaque fil Matrix possède sa propre session. Sans fil Matrix existant, la création automatique peut en démarrer un depuis l’événement entrant.',
    'web.channels.settings.connection.sync': 'Synchronisation (interrogation longue)',
    'web.channels.settings.connection.gateway': 'Passerelle (WebSocket)',
    'web.channels.settings.connection.ilink': 'iLink (interrogation longue)',
    'web.channels.settings.connection.websocket': 'WebSocket (connexion longue)',
    'web.channels.settings.connectionHelp.matrix': 'L’API interroge Matrix /sync avec le jeton d’accès du bot — aucune URL publique ni configuration de rappel nécessaire. Les salons chiffrés ne sont pas pris en charge ; les événements chiffrés sont ignorés.',
    'web.channels.settings.connectionHelp.discord': 'L’API maintient une connexion Discord Gateway — aucune URL publique ni configuration de rappel nécessaire. Vérifiez que MESSAGE_CONTENT est activé dans le Developer Portal, sous Bot → Privileged Gateway Intents.',
    'web.channels.settings.connectionHelp.weixin': 'L’API interroge longuement la passerelle Tencent iLink avec le jeton du bot — aucune URL publique nécessaire. WeChat personnel fonctionne uniquement par message privé ; les chats de groupe ne sont pas transmis. Si la session expire (errcode -14), rescanez le code QR et mettez à jour le jeton.',
    'web.channels.settings.webhookHelp.telegram': 'Le webhook Telegram est enregistré automatiquement lorsque les identifiants sont enregistrés — rien à coller.',
    'web.channels.settings.webhookHelp.slack': 'Collez cette URL dans votre application Slack, sous Event Subscriptions → Request URL.',
    'web.channels.settings.webhookHelp.lark': 'Collez ceci dans {{platform}} Open Platform → Event Subscriptions → Request URL.',
    'web.channels.settings.webhookHelp.github': 'Le flux de création de l’application GitHub définit automatiquement cette URL de webhook ; pour une application créée manuellement, définissez-la comme URL de webhook de l’application avec les événements issues et issue_comment.',
    'web.channels.settings.webhookHelp.other': 'Collez cette URL dans la configuration d’abonnement aux événements de votre fournisseur.',
    'web.channels.settings.webhookHelp.line': 'L\'URL du webhook LINE est configurée automatiquement à l\'enregistrement des identifiants — rien à coller. Activez « Use webhook » dans la console LINE Developers sous Messaging API, et désactivez-y les réponses automatiques pour que le bot ne réponde pas deux fois.',
    'web.channels.settings.github.title': 'Application GitHub',
    'web.channels.settings.github.connectedAs': 'Connecté en tant que',
    'web.channels.settings.github.mentionHint': '. Mentionnez-la dans une issue ou un commentaire pour démarrer un tour.',
    'web.channels.settings.github.install': 'Installer sur les dépôts',
    'web.channels.settings.github.installHint': 'L’application doit être installée sur chaque dépôt auquel l’agent doit répondre. L’accès en écriture au dépôt (clonage/push/PR) provient d’une connexion GitHub liée au même agent, pas de cette application.',
    'web.channels.settings.github.createHint': 'Créez une application GitHub dédiée à ce canal — GitHub renvoie automatiquement les identifiants et le canal s’active lui-même. Laissez l’organisation vide pour la créer sur votre compte personnel.',
    'web.channels.settings.github.create': 'Créer une application GitHub',
    'web.channels.settings.slack.manifest': 'Manifeste de l’application Slack',
    'web.channels.settings.slack.copyManifest': 'Copier le JSON du manifeste',
    'web.channels.settings.slack.manifestHint': 'Créez l’application Slack depuis un manifeste et collez ce JSON. Il configure l’URL de demande, les abonnements aux événements, les scopes du bot et toutes les commandes slash de ce canal. Si une autre application installée revendique déjà un nom de commande (par ex.',
    'web.channels.settings.slack.manifestHintSuffix': '), Slack vous avertit lors de l’installation — renommez-la d’abord dans le manifeste. Invitez le bot dans chaque canal afin qu’il puisse publier.',
