    'web.channels.settings.placeholders.delegationLabel': 'par ex. agent',
    'web.channels.settings.setupMode.lark': 'Mode de configuration Lark',
    'web.channels.settings.setupMode.weixin': 'Mode de configuration WeChat',
    'web.channels.settings.help.telegramCreate': 'Créez un bot via @BotFather et collez le jeton. Nous enregistrerons le webhook pour vous.',
    'web.channels.settings.help.telegramEdit': 'Laissez les utilisateurs ou chats de groupe autorisés vides pour permettre l’accès à tous. Les opérateurs peuvent exécuter des commandes à l’échelle de l’agent comme /model ; sans opérateurs, ces commandes sont désactivées sur Telegram.',
    'web.channels.settings.help.slackCreate': 'Après l’enregistrement, collez l’URL entrante du canal dans votre application Slack, sous Event Subscriptions. Laissez les utilisateurs autorisés vides pour permettre à tous les membres de l’espace de travail d’utiliser le bot. Les opérateurs peuvent exécuter des commandes comme /model ; sans opérateurs, /model est désactivé sur Slack.',
    'web.channels.settings.help.slackEdit': 'Laissez les utilisateurs autorisés vides pour permettre à tous les membres de l’espace de travail d’utiliser le bot. Les opérateurs peuvent exécuter des commandes comme /model ; sans opérateurs, /model est désactivé sur Slack.',
    'web.channels.settings.help.linearCreate': 'Créez une application dans votre espace Linear, activez les webhooks avec les événements de session d’agent et collez-y l’URL entrante du canal après l’enregistrement. Les identifiants client permettent à Manyfold de créer son propre jeton d’application ; fournissez plutôt un jeton d’accès si vous en avez créé un vous-même. Laissez les utilisateurs autorisés vides pour permettre à tous les membres de l’espace de travail de mentionner l’agent.',
    'web.channels.settings.help.githubCreate': 'Créez d’abord le canal, puis utilisez « Créer une application GitHub » sur sa page — GitHub renvoie automatiquement les identifiants de l’application. Mentionnez l’application dans une issue pour démarrer un tour. Laissez les dépôts vides pour répondre sur chaque dépôt où l’application est installée.',
    'web.channels.settings.help.discordCreate': 'Discord utilise un WebSocket Gateway — aucune URL publique nécessaire. Activez l’intention MESSAGE_CONTENT dans le Developer Portal, sous Bot → Privileged Gateway Intents, sinon le bot ne verra pas le texte des messages.',
    'web.channels.settings.help.matrixCreate': 'Matrix utilise l’interrogation longue /sync — aucune URL de webhook nécessaire. Les salons chiffrés ne sont pas pris en charge ; les événements chiffrés sont ignorés.',
    'web.channels.settings.help.weixinCreate': 'WeChat personnel via la passerelle de bot Tencent iLink — messages privés uniquement, aucune URL de webhook nécessaire. Laissez les ID d’opérateurs vides pour désactiver les commandes à l’échelle de l’agent.',
    'web.channels.settings.help.larkManual': 'Laissez les utilisateurs autorisés vides pour permettre à tous de joindre le bot. Les opérateurs peuvent exécuter des commandes comme /model ; sans opérateurs, /model est désactivé dans Feishu/Lark.',
    'web.channels.settings.help.weixinEdit': 'WeChat personnel fonctionne uniquement par message privé. Laissez les ID d’opérateurs vides pour désactiver les commandes à l’échelle de l’agent (par ex. /model).',
    'web.channels.settings.help.whatsappEdit': 'WhatsApp se connecte via WhatsApp Web : ce canal n\'a donc besoin d\'aucune URL de webhook. Laissez les expéditeurs ou les groupes autorisés vides pour n\'imposer aucune restriction. Les opérateurs peuvent exécuter des commandes globales comme /model ; sans opérateur, ces commandes sont désactivées depuis WhatsApp. Les expéditeurs s\'écrivent sous forme de numéro de téléphone ou de jid.',
    'web.channels.settings.help.linearEdit': 'L’activité affiche la réflexion, les appels d’outils et le plan dans la session Linear pendant le travail de l’agent ; Final uniquement ne publie que le résultat. La rotation des identifiants les remplace tous en une fois : saisissez à nouveau le secret de signature lors de toute modification.',
    'web.channels.settings.help.githubEdit': 'Les identifiants autorisés vides utilisent la règle d’association (propriétaire du dépôt, membres de l’organisation et collaborateurs par défaut — ajoutez NONE pour l’ouvrir). Ajouter le libellé de délégation à une issue démarre un tour sans mention. Laissez les identifiants d’opérateurs vides pour désactiver les commandes à l’échelle de l’agent (par ex. /model).',
    'web.channels.settings.help.lineCreate': 'Créez un canal Messaging API dans la console LINE Developers, émettez un channel access token de longue durée et collez les deux ici. Nous configurons l\'URL du webhook pour vous — vous devez encore activer « Use webhook » dans la console. Les réponses sont en texte brut sans aperçu en direct, et chacune est décomptée du quota de messages de votre offre LINE.',
    'web.channels.settings.help.lineEdit': 'Laissez les utilisateurs ou les ID de groupe autorisés vides pour autoriser tout le monde. Les opérateurs peuvent exécuter des commandes globales comme /model ; sans opérateur, ces commandes sont désactivées depuis LINE. La rotation remplace les deux identifiants d\'un coup : ressaisissez le channel secret et l\'access token ensemble.',
    'web.channels.settings.errors.larkWebhookCredentials': 'Les canaux webhook Lark/Feishu nécessitent un jeton de vérification ou une clé de chiffrement.',
    'web.channels.settings.errors.linearCredentials': 'Linear nécessite soit un jeton d’accès, soit un ID client et un secret client',
    'web.channels.settings.errors.matrixHomeserver': 'L’URL du homeserver Matrix est obligatoire.',
    'web.channels.settings.errors.matrixAccessToken': 'Le jeton d’accès Matrix est obligatoire.',
    'web.channels.settings.errors.slackCredentials': 'La rotation du jeton Slack nécessite à la fois le jeton du bot et le secret de signature.',
    'web.channels.settings.errors.linearRotation': 'La rotation des identifiants Linear nécessite le secret de signature du webhook ainsi qu’un jeton d’accès, ou un ID client et un secret client.',
    'web.channels.settings.errors.githubRotation': 'La rotation des identifiants GitHub nécessite l’ID de l’application, la clé privée et le secret du webhook ensemble.',
    'web.channels.settings.errors.weixinBotToken': 'Le jeton du bot WeChat iLink est obligatoire.',
    'web.channels.settings.errors.lineCredentials': 'LINE nécessite à la fois un channel secret et un channel access token.',
    'web.channels.settings.errors.lineRotation': 'La rotation des identifiants LINE nécessite le channel secret et le channel access token ensemble.',
